function startLesson(focusId){closeModal();const p=activeProfile(),ids=C.learnedSkillsThrough(p,focusId);runSession({title:`Học · ${C.getSkill(focusId).title}`,purpose:'lesson',focusId,skillIds:ids,limit:12});}
