function startReview(){const ids=C.dueSkills(activeProfile()).slice(0,12);if(!ids.length)return alert('Hiện chưa có kỹ năng đến hạn ôn.');runSession({title:'Ôn đúng lúc',purpose:'review',skillIds:ids,limit:12});}
