 if(cfg.memory){const area=shell.querySelector('#answerArea');area.innerHTML=`<div class="countdown">Hãy ghi phép tính vào đầu…</div>`;flashTimer=setTimeout(()=>{shell.querySelector('#questionArea').className='flash-cover';shell.querySelector('#questionArea').textContent='Đề đã được che';qStart=Date.now();showChoices();},cfg.flashMs||4500);}else{qStart=Date.now();showChoices();}
