function resetSlot(){if(!confirm(`Xóa toàn bộ dữ liệu học của “${currentName()}”? Dữ liệu Kanban không bị ảnh hưởng.`))return;state.profiles[state.activeSlot]=C.emptyProfile();state.stats[state.activeSlot]=emptyStats();saveState();render();}

view.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.act==='placement')startPlacement();else if(el.dataset.act==='lesson'){const id=C.chooseLessonSkill(activeProfile());showSkillIntro(id);}else if(el.dataset.act==='review')startReview();else if(el.dataset.act==='memory'||el.dataset.act==='start-memory')navigate(el.dataset.act==='memory'?'memory':'memory'),el.dataset.act==='start-memory'&&startMemory();else if(el.dataset.act==='times')showTimesTables();else if(el.dataset.act==='rename'){const input=document.getElementById('renameInput'),name=input?.value.trim();if(name){state.slots[state.activeSlot].name=name.slice(0,24);saveState();render();}}else if(el.dataset.act==='reset-slot')resetSlot();else if(el.dataset.op){skillOperation=el.dataset.op;renderSkills();}else if(el.dataset.skill)showSkillIntro(el.dataset.skill);else if(el.dataset.boss)startBoss(el.dataset.boss);else if(el.dataset.slot){state.activeSlot=el.dataset.slot;saveState();render();}});
modalRoot.addEventListener('click',e=>{const back=e.target.closest('[data-return-kanban]');if(back){e.preventDefault();requestReturnToKanban();return;}if(e.target.matches('[data-close-modal]')||e.target.closest('[data-modal-x]')){closeModal();return;}const sl=e.target.closest('[data-slot-modal]');if(sl){state.activeSlot=sl.dataset.slotModal;saveState();closeModal();render();return;}const start=e.target.closest('[data-start-lesson]');if(start){startLesson(start.dataset.startLesson);return;}const skip=e.target.closest('[data-skip-check]');if(skip){startSkipCheck(skip.dataset.skipCheck);return;}const tb=e.target.closest('[data-table]');if(tb)renderTable(Number(tb.dataset.table));});
